/** Registers the Workbox service worker generated by vite-plugin-pwa (production only). */
export function registerServiceWorker(): void {
  if (!import.meta.env.PROD || !('serviceWorker' in navigator)) return;
  import('virtual:pwa-register')
    .then(({ registerSW }) => {
      registerSW({
        immediate: true,
        onOfflineReady() {
          console.info('Servolab is ready to work offline.');
        },
        onRegisterError(err: unknown) {
          console.warn('Service worker registration failed', err);
        }
      });
    })
    .catch(() => {
      /* PWA module unavailable (e.g. dev) */
    });
}
